 ink='#e4ebef' if dark else '#242d33';bars=('#95a5af' if dark else '#6f7e88') if color else None;red=BRAND_RED if color else None
 board+=f'<div class="tile {"dark" if dark else ""}"><small>{key} / {"DARK GROUND" if dark else "LIGHT GROUND"}</small><div class="lockup">'+svg(ink=ink,bars=bars,accent=red,ident=key+str(dark))+'<strong>les Privilege</strong></div></div>'
